templates.code:
startupProbe:
  httpGet:
    path: {ruta_listo}
    port: {puerto}
  periodSeconds: {periodo}
  failureThreshold: {fallos}

readinessProbe:
  httpGet:
    path: {ruta_listo}
    port: {puerto}
  periodSeconds: {periodo}
  timeoutSeconds: {timeout}
  failureThreshold: {fallos}

livenessProbe:
  httpGet:
    path: {ruta_vivo}
    port: {puerto}
  periodSeconds: {periodo}
  timeoutSeconds: {timeout}
  failureThreshold: {fallos}

spec:
  terminationGracePeriodSeconds: {gracia}
  containers:
    - name: {contenedor}
      lifecycle:
        preStop:
          sleep:
            seconds: {espera}

resources:
  requests:
    cpu: "{cpu}"
    memory: {mem}
  limits:
    memory: {mem}

resources:
  requests:
    cpu: "{cpu}"
    memory: {mem}
    nvidia.com/gpu: {gpus}
  limits:
    memory: {mem}
    nvidia.com/gpu: {gpus}

kubectl describe node {nodo}
kubectl get pod {pod} -o jsonpath='{.status.qosClass}'
kubectl top pod {pod} --containers

kubectl create configmap {cm} --from-literal={CLAVE}={valor}
kubectl create secret generic {secreto} --from-literal={CLAVE}={valor}
kubectl rollout restart deployment/{deploy}

envFrom:
  - configMapRef:
      name: {cm}
env:
  - name: {VAR}
    valueFrom:
      secretKeyRef:
        name: {secreto}
        key: {CLAVE}

volumeMounts:
  - name: {vol}
    mountPath: {ruta}
    readOnly: true
volumes:
  - name: {vol}
    configMap:
      name: {cm}
  - name: {tmp}
    emptyDir:
      sizeLimit: {tamaño}

# en el pod
serviceAccountName: {sa}
# IRSA: anotación en la ServiceAccount
kubectl annotate serviceaccount {sa} -n {ns} eks.amazonaws.com/role-arn=arn:aws:iam::{cuenta}:role/{rol}
# EKS Pod Identity: asociación en EKS, sin anotación
aws eks create-pod-identity-association --cluster-name {cluster} --namespace {ns} --service-account {sa} --role-arn arn:aws:iam::{cuenta}:role/{rol}

spec:
  nodeSelector:
    {label}: {valor}
  tolerations:
    - key: {clave_taint}
      operator: Equal
      value: {valor_taint}
      effect: NoSchedule

topologySpreadConstraints:
  - maxSkew: {sesgo}
    topologyKey: topology.kubernetes.io/zone
    whenUnsatisfiable: {si_no_cabe}
    labelSelector:
      matchLabels:
        app.kubernetes.io/name: {app}

behavior:
  scaleUp:
    stabilizationWindowSeconds: 0
    policies:
      - type: Pods
        value: {pods_por_periodo}
        periodSeconds: {periodo}
  scaleDown:
    stabilizationWindowSeconds: {ventana}

apiVersion: keda.sh/v1alpha1
kind: ScaledObject
metadata:
  name: {nombre}
spec:
  scaleTargetRef:
    name: {deployment}
  minReplicaCount: {min}
  maxReplicaCount: {max}
  triggers:
    - type: prometheus
      metricType: Value
      metadata:
        serverAddress: {url_prometheus}
        query: {query}
        threshold: "{umbral}"

kubectl get hpa -n {ns} -w
kubectl describe hpa {nombre} -n {ns}
kubectl get scaledobject -n {ns}
kubectl get hpa keda-hpa-{nombre} -n {ns}
